      en: ["The historic center of Bukhara was added to the UNESCO World Heritage List in 1993.", "The Kalyan Minaret was completed in 1127 and stands 47 meters tall.", "The Samanid Mausoleum dates back to approximately 905 AD.", "The Ark of Bukhara fortress served as a royal residence since the 5th century.", "The legendary scholar Avicenna was born in a village near Bukhara in 980 AD.", "Bukhara contains more than 140 officially protected architectural monuments."],
      es: ["Bujará cuenta con un asentamiento continuo de más de 2500 años.", "El minarete de Kalon fue construido en 1127 y tiene 47 metros de altura.", "El mausoleo de los Samánidas se completó alrededor del año 905.", "La fortaleza de la ciudad, Ark, sirvió como residencia de los emires de Bujará hasta 1920.", "La UNESCO declaró el centro histórico Patrimonio de la Humanidad en 1993.", "Hay más de 140 monumentos protegidos en el casco antiguo."],
