    type: "city",
    parent: "UZ-NG",
    coords: [71.6726, 41.0011],
    name: { de: "Namangan", hu: "Namangan", ro: "Namangan", en: "Namangan"},
    image: "/poi-images/namangan-cities-v2.webp",
    description: {
      de: "Wichtige Industriestadt im Ferghanatal, bekannt für ihre Textil- und Lebensmittelproduktion.",
      hu: "Fontos ipari város a Fergana-völgyben, textil- és élelmiszeriparáról ismert.",
      ro: "Oraș industrial important din Valea Fergana, cunoscut pentru producția sa textilă și alimentară.",
      en: "Important industrial city in the Fergana Valley, known for its textile and food production.",
      es: "Importante ciudad industrial en el valle de Fergana, conocida por su producción textil y alimentaria.",
      pt: "Importante cidade industrial no vale de Fergana, conhecida pela sua produção têxtil e alimentar.",
      fr: "Ville industrielle importante dans la vallée de Ferghana, connue pour sa production textile et alimentaire.",
    },
    descriptionAdvanced: {
      de: "Namangan liegt im fruchtbaren Ferghanatal im Osten Usbekistans und ist mit über 600.000 Einwohnern die drittgrößte Stadt des Landes. Sie entstand im 17. Jahrhundert aus mehreren Dörfern und wuchs schnell zum Handelszentrum für Baumwolle, Obst und Seide. Heute prägen Textilfabriken, Nahrungsmittelverarbeitung und der berühmte Obstbau die lokale Wirtschaft; Granatäpfel, Aprikosen und Quitten aus Namangan sind in ganz Zentralasien begehrt. Die Stadt gilt als religiös konservativ und besitzt mehrere historische Medresen wie die Mullah-Kyrgyz- und die Khoja-Amin-Medrese. Im Babur-Park, benannt nach dem Mogulgründer aus dem nahen Andidschan, finden Familien an heißen Sommertagen Erholung. Namangan ist auch ein Verkehrsknotenpunkt mit Eisenbahnverbindungen nach Taschkent und Andidschan.",
      hu: "Namangan a termékeny Fergánai-medencében, Üzbegisztán keleti részén fekszik, és több mint 600 ezer lakosával az ország harmadik legnagyobb városa. A 17. században jött létre több falu egyesüléséből, majd gyorsan a gyapot-, gyümölcs- és selyemkereskedelem központjává vált. A mai gazdaságot a textilipar, az élelmiszer-feldolgozás és a híres gyümölcstermesztés határozza meg; a namangani gránátalma, sárgabarack és birsalma egész Közép-Ázsiában keresett. A város vallásilag konzervatívnak számít, és több történelmi medresze is megtalálható itt, például a Mullah-Kirgiz- és a Hodzsa-Amin-medresze. A közeli Andidzsánból származó mogul birodalomalapítóról elnevezett Bábur park forró nyári napokon a családok kedvelt menedéke. Namangan egyben fontos közlekedési csomópont is, vasúti összeköttetéssel Taskent és Andidzsán felé.",
      ro: "Namangan este situat în fertila vale Fergana, în estul Uzbekistanului, și cu peste 600.000 de locuitori este al treilea oraș ca mărime din țară. A luat naștere în secolul al XVII-lea prin unirea mai multor sate și s-a transformat rapid într-un centru comercial pentru bumbac, fructe și mătase. Astăzi, economia locală este dominată de fabricile textile, prelucrarea alimentelor și pomicultura celebră; rodiile, caisele și gutuile din Namangan sunt căutate în întreaga Asie Centrală. Orașul este considerat conservator din punct de vedere religios și găzduiește mai multe medrese istorice, precum Mullah-Kîrgîz și Khoja-Amin. Parcul Babur, numit după fondatorul mogul originar din apropiatul Andijan, este un loc preferat de familii în zilele călduroase de vară. Namangan este și un nod important de transport, cu legături feroviare către Tașkent și Andijan.",
      en: "Namangan lies in the fertile Fergana Valley in eastern Uzbekistan and, with over 600,000 residents, is the country's third-largest city. It emerged in the seventeenth century through the merger of several villages and quickly grew into a trading hub for cotton, fruit, and silk. Today the local economy is shaped by textile mills, food processing, and the region's famous orchards; pomegranates, apricots, and quinces from Namangan are prized across Central Asia. The city is considered religiously conservative and hosts several historic madrasas such as Mullah-Kyrgyz and Khoja-Amin. Babur Park, named after the Mughal founder born in nearby Andijan, is a popular family retreat during the hot summer months. Namangan is also a major transport hub with rail connections to Tashkent and Andijan.",
      es: "Namangan se encuentra en el fértil valle de Fergana, al este de Uzbekistán, y con más de 600.000 habitantes es la tercera ciudad más grande del país. Surgió en el siglo XVII a partir de varias aldeas y creció rápidamente como centro comercial de algodón, frutas y seda. Hoy en día, las fábricas textiles, el procesamiento de alimentos y el famoso cultivo de frutas marcan la economía local; las granadas, los albaricoques y los membrillos de Namangan son codiciados en toda Asia Central. La ciudad se considera religiosamente conservadora y posee varias madrasas históricas como la de Mullah-Kyrgyz y la de Khoja-Amin. En el Parque Babur, que lleva el nombre del fundador mogol procedente de la cercana Andiján, las familias encuentran descanso en los calurosos días de verano. Namangan es también un nudo de comunicaciones con conexiones ferroviarias a Taskent y Andiján.",
      pt: "Namangan localiza-se no fértil vale de Fergana, no leste do Usbequistão, e é a terceira maior cidade do país, com mais de 600.000 habitantes. Surgiu no século XVII a partir de várias aldeias e cresceu rapidamente como um centro comercial de algodão, fruta e seda. Atualmente, as fábricas têxteis, o processamento de alimentos e a famosa fruticultura moldam a economia local; as romãs, os damascos e os marmelos de Namangan são procurados em toda a Ásia Central. A cidade é considerada religiosamente conservadora e possui várias madraças históricas, como a Mullah-Kyrgyz e a Khoja-Amin. No Parque Babur, batizado em honra do fundador mogol da vizinha Andijã, as famílias encontram descanso nos dias quentes de verão. Namangan é também um nó de transportes com ligações ferroviárias para Tasquente e Andijã.",
      fr: "Namangan est située dans la fertile vallée de Ferghana, à l'est de l'Ouzbékistan, et constitue avec plus de 600 000 habitants la troisième ville du pays. Née au XVIIe siècle de la réunion de plusieurs villages, elle est rapidement devenue un centre commercial pour le coton, les fruits et la soie. Aujourd'hui, les usines textiles, la transformation alimentaire et la célèbre arboriculture marquent l'économie locale ; les grenades, les abricots et les coings de Namangan sont prisés dans toute l'Asie centrale. La ville est considérée comme religieusement conservatrice et possède plusieurs médersas historiques, telles que les médersas Moulla-Kirghiz et Khoja-Amin. Dans le parc Babur, du nom du fondateur de l'empire moghol originaire d'Andijan voisine, les familles trouvent de la fraîcheur lors des chaudes journées d'été. Namangan est également un nœud de communication avec des liaisons ferroviaires vers Tachkent et Andijan.",
    },
