      pt: ["O Museu Savitsky abriga a segunda maior coleção de arte de vanguarda russa do mundo.", "Está rodeada por três desertos diferentes: Karakum, Kyzylkum e Ustyurt.", "A cidade viveu um boom desde 1960 como centro de investigação e indústria.", "Situa-se numa região fortemente afetada pela dessecação do mar de Aral."],
      fr: ["Le musée Savitsky abrite la deuxième plus grande collection d'art d'avant-garde russe au monde.", "Elle est entourée de trois déserts différents : le Karakoum, le Kyzylkoum et l'Oustyourt.", "La ville a connu un essor depuis 1960 en tant que centre de recherche et d'industrie.", "Elle se trouve dans une région fortement touchée par l'assèchement de la mer d'Aral."],
