      es: ["Surgió en la década de 1930 durante la construcción de centrales hidroeléctricas en el río Chirchiq.", "Posee una industria química y de ingeniería mecánica muy desarrollada.", "Durante la Segunda Guerra Mundial, numerosas fábricas fueron evacuadas aquí.", "Cerca de la ciudad se encuentra una gran zona de deportes de invierno llamada Beldersay."],
      pt: ["Surgiu na década de 1930 durante a construção de centrais hidroelétricas no rio Chirchiq.", "Possui uma indústria química e mecânica fortemente desenvolvida.", "Durante a Segunda Guerra Mundial, numerosas fábricas foram evacuadas para aqui.", "Perto da cidade encontra-se uma grande estância de desportos de inverno chamada Beldersay."],
      fr: ["A été créée dans les années 1930 lors de la construction de centrales hydroélectriques sur la rivière Tchirtchik.", "Possède une industrie chimique et de construction mécanique très développée.", "De nombreuses usines y ont été évacuées pendant la Seconde Guerre mondiale.", "Un grand domaine de sports d'hiver nommé Beldersay se trouve à proximité de la ville."],
