    name: { de: "Angren", hu: "Angren", ro: "Angren", en: "Angren"},
    image: "/poi-images/angren-cities-v2.webp",
    description: {
      de: "Zentrum des Kohlebergbaus und der Energiewirtschaft in der Region Taschkent.",
      hu: "A szénbányászat és az energiaipar központja Taskent tartományban.",
      ro: "Centrul mineritului de cărbune și al industriei energetice din regiunea Tașkent.",
      en: "Center of coal mining and the energy industry in the Tashkent region.",
      es: "Centro de la minería del carbón y de la industria energética en la región de Tashkent.",
      pt: "Centro de mineração de carvão e da indústria energética na região de Tashkent.",
      fr: "Centre de l'exploitation minière du charbon et de l'énergie dans la région de Tachkent.",
    },
    descriptionAdvanced: {
      de: "Angren liegt etwa 110 Kilometer östlich von Taschkent im Tal des gleichnamigen Flusses und ist eines der wichtigsten Bergbauzentren Usbekistans. Die Stadt wurde 1946 gegründet, als die sowjetische Regierung große Braunkohlevorkommen erschloss, um die wachsende Hauptstadt mit Energie zu versorgen. Mit rund 180.000 Einwohnern wirkt das Stadtbild noch immer von Plattenbauten und Förderanlagen geprägt. Neben Kohle werden hier auch Kaolin, Bentonit und Goldschiefer gefördert. In jüngerer Zeit hat sich Angren zu einer Sonderwirtschaftszone entwickelt, in der Maschinenbau, Lebensmittelindustrie und Logistik angesiedelt sind. Wichtige Verkehrsachsen sind die Eisenbahnstrecke nach China sowie der 2016 eröffnete Kamtschik-Tunnel, der das Ferghanatal mit der Hauptstadtregion verbindet und früher umständliche Routen über Tadschikistan ersetzt.",
      hu: "Angren mintegy 110 kilométerre keletre fekszik Taskenttől, az azonos nevű folyó völgyében, és Üzbegisztán egyik legfontosabb bányavárosa. 1946-ban alapították, amikor a szovjet kormány hozzálátott a hatalmas barnaszénvagyon kitermeléséhez, hogy ellássa energiával a növekvő fővárost. Mintegy 180 ezer lakosával a városképet ma is panelházak és bányászati létesítmények határozzák meg. A szén mellett kaolint, bentonitot és aranypalát is bányásznak itt. Az utóbbi években Angren különleges gazdasági övezetté alakult, ahol gépipar, élelmiszeripar és logisztikai cégek telepedtek meg. Fontos közlekedési tengelyek a Kínába vezető vasútvonal, valamint a 2016-ban átadott Kamcsik-alagút, amely a Fergánai-völgyet köti össze a fővárosi régióval, kiváltva a korábbi, Tádzsikisztánon át vezető körülményes útvonalakat.",
      ro: "Angren este situat la aproximativ 110 kilometri est de Tașkent, în valea râului cu același nume, și este unul dintre cele mai importante centre miniere din Uzbekistan. Orașul a fost fondat în 1946, când guvernul sovietic a început exploatarea zăcămintelor uriașe de lignit pentru a alimenta cu energie capitala în plină creștere. Cu aproximativ 180.000 de locuitori, peisajul urban este încă marcat de blocurile prefabricate și instalațiile miniere. Pe lângă cărbune, aici se mai extrag caolin, bentonită și șisturi aurifere. În ultimii ani, Angren s-a transformat într-o zonă economică specială care găzduiește construcția de mașini, industria alimentară și logistica. Axele importante de transport sunt linia ferată spre China și tunelul Kamcik, deschis în 2016, care leagă valea Fergana de regiunea capitalei, înlocuind rutele anevoioase prin Tadjikistan.",
      en: "Angren lies some 110 kilometres east of Tashkent in the valley of the river of the same name and is one of Uzbekistan's most important mining cities. It was founded in 1946 when the Soviet government began tapping the huge brown-coal deposits to power the rapidly growing capital. With around 180,000 inhabitants, its skyline is still marked by prefabricated apartment blocks and mining facilities. Besides coal, kaolin, bentonite, and gold-bearing schist are also extracted here. In recent years Angren has been transformed into a special economic zone hosting machine building, food industries, and logistics. Major transport links include the railway line to China and the Kamchik Tunnel, opened in 2016, which connects the Fergana Valley with the Tashkent region and has replaced the cumbersome routes that previously had to pass through Tajikistan.",
      es: "Angren se encuentra a unos 110 kilómetros al este de Tashkent, en el valle del río homónimo, y es uno de los centros mineros más importantes de Uzbekistán. La ciudad fue fundada en 1946, cuando el gobierno soviético desarrolló grandes yacimientos de lignito para abastecer de energía a la creciente capital. Con unos 180.000 habitantes, el paisaje urbano sigue marcado por edificios prefabricados e instalaciones de extracción. Además de carbón, aquí se extraen caolín, bentonita y esquisto aurífero. Recientemente, Angren se ha convertido en una zona económica especial que alberga industrias de ingeniería, alimentación y logística. Los ejes de transporte más importantes son la línea ferroviaria hacia China y el túnel de Kamchik, inaugurado en 2016, que conecta el valle de Ferganá con la región de la capital, sustituyendo a las antiguas y complicadas rutas a través de Tayikistán.",
      pt: "Angren está localizada a cerca de 110 quilómetros a leste de Tashkent, no vale do rio homónimo, e é um dos centros mineiros mais importantes do Uzbequistão. A cidade foi fundada em 1946, quando o governo soviético explorou grandes depósitos de lenhite para fornecer energia à capital em crescimento. Com cerca de 180.000 habitantes, a paisagem urbana ainda é marcada por prédios de betão e instalações de extração. Além do carvão, também são extraídos caulim, bentonite e xisto dourado. Recentemente, Angren tornou-se uma zona económica especial, onde se instalaram indústrias mecânicas, alimentares e de logística. Eixos de transporte importantes são a linha ferroviária para a China e o túnel Kamchik, inaugurado em 2016, que liga o Vale de Fergana à região da capital, substituindo as rotas complicadas através do Tajiquistão.",
      fr: "Angren se situe à environ 110 kilomètres à l'est de Tachkent, dans la vallée de la rivière du même nom, et constitue l'un des plus importants centres miniers d'Ouzbékistan. La ville a été fondée en 1946 lorsque le gouvernement soviétique a exploité de grands gisements de lignite pour alimenter en énergie la capitale en pleine croissance. Avec environ 180 000 habitants, le paysage urbain reste marqué par des immeubles en préfabriqué et des installations d'extraction. Outre le charbon, on y extrait du kaolin, de la bentonite et du schiste aurifère. Plus récemment, Angren est devenue une zone économique spéciale accueillant des entreprises de construction mécanique, d'agroalimentaire et de logistique. Les axes de transport majeurs sont la ligne de chemin de fer vers la Chine ainsi que le tunnel de Kamtchik, inauguré en 2016, qui relie la vallée de Ferghana à la région de la capitale, remplaçant les anciens itinéraires complexes via le Tadjikistan.",
    },
