      es: ["La ciudad fue fundada en 1946 tras el hallazgo de grandes yacimientos de carbón.", "Una central eléctrica cercana abastece de energía a gran parte de la región de Tashkent.", "Está situada en la importante línea de ferrocarril que conecta el valle de Ferganá con el resto del país.", "Las montañas circundantes convierten a la ciudad en un punto de partida para excursiones alpinas."],
      pt: ["A cidade foi fundada em 1946 após a descoberta de grandes depósitos de carvão.", "Uma central elétrica próxima fornece energia a grande parte da região de Tashkent.", "Situa-se na importante linha ferroviária que liga o Vale de Fergana ao resto do país.", "As montanhas circundantes tornam a cidade um ponto de partida para caminhadas."],
      fr: ["La ville a été fondée en 1946 suite à la découverte de vastes gisements de charbon.", "Une centrale électrique voisine alimente en énergie une grande partie de la région de Tachkent.", "Se trouve sur la ligne de chemin de fer majeure reliant la vallée de Ferghana au reste de l'Ouzbékistan.", "Les montagnes environnantes font de la ville un point de départ pour des randonnées pédestres."],
