    coords: [69.2661, 40.2197],
    name: { de: "Bekabad", hu: "Bekabad", ro: "Bekobod", en: "Bekabad"},
    image: "/poi-images/bekabad-cities-v2.webp",
    description: {
      de: "Eine am Fluss Syrdarja gelegene Stadt, die für ihre Stahlindustrie bekannt ist.",
      hu: "A Szir-darja folyó partján fekvő város, amely acéliparáról ismert.",
      ro: "Un oraș situat pe râul Sîrdaria, cunoscut pentru industria sa siderurgică.",
      en: "A city located on the Syr Darya river, known for its steel industry.",
      es: "Una ciudad situada a orillas del río Sir Daria, conocida por su industria del acero.",
      pt: "Uma cidade situada no rio Syr Darya, conhecida pela sua indústria siderúrgica.",
      fr: "Une ville située sur les rives du Syr-Daria, célèbre pour son industrie sidérurgique.",
    },
    descriptionAdvanced: {
      de: "Bekabad liegt am Sirdarja, im Süden der Provinz Taschkent, direkt an der Grenze zu Tadschikistan. Mit rund 95.000 Einwohnern ist die Stadt vor allem als Sitz des größten Stahlwerks Zentralasiens, des Uzmetkombinat, bekannt. Es wurde 1942 gegründet, als sowjetische Schwerindustriebetriebe vor der heranrückenden deutschen Front nach Osten verlegt wurden. Bis heute beschäftigt das Werk mehrere Tausend Menschen und produziert Walzstahl, Bewehrungsstahl und Bahnschienen. Daneben gibt es ein bedeutendes Zementwerk und ein Wasserkraftwerk am Fars-Hatschan-Stausee. Bekabad spielt auch geopolitisch eine Rolle, da die Eisenbahn- und Straßenverbindungen mehrfach die tadschikisch-usbekische Grenze kreuzen, was nach der Unabhängigkeit der beiden Länder zu komplizierten Transitlösungen führte.",
      hu: "Bekabad a Szir-darja partján, Taskent tartomány déli részén, közvetlenül a tádzsik határ mellett fekszik. Mintegy 95 ezer lakosával elsősorban Közép-Ázsia legnagyobb acélművének, az Uzmetkombinat üzemnek a székhelyeként ismert. A művet 1942-ben hozták létre, amikor a szovjet nehézipar üzemeit a közelgő német front elől keletre telepítették. A gyár ma is több ezer embert foglalkoztat, és hengerelt acélt, bétonacélt és vasúti síneket gyárt. Emellett jelentős cementgyár és a Fars-Hatcsan tározónál egy vízerőmű is működik a városban. Bekabad geopolitikai szempontból is fontos: a vasúti és közúti összeköttetések többször keresztezik a tádzsik-üzbég határt, ami a két ország függetlenedése után bonyolult átkelési megoldásokhoz vezetett.",
      ro: "Bekabad se află pe râul Sîr-Daria, în sudul provinciei Tașkent, chiar la granița cu Tadjikistanul. Cu aproximativ 95.000 de locuitori, orașul este cunoscut mai ales ca sediu al celei mai mari oțelării din Asia Centrală, Uzmetkombinat. Aceasta a fost înființată în 1942, când unele întreprinderi sovietice de industrie grea au fost mutate spre est, departe de frontul german care înainta. Și astăzi uzina dă de lucru mai multor mii de oameni și produce oțel laminat, oțel-beton și șine de cale ferată. În plus, în oraș funcționează o fabrică importantă de ciment și o hidrocentrală pe lacul de acumulare Fars-Hatchan. Bekabad joacă un rol și din perspectivă geopolitică: liniile ferate și șoselele traversează de mai multe ori granița dintre Tadjikistan și Uzbekistan, ceea ce, după independența celor două țări, a dus la soluții de tranzit complicate.",
      en: "Bekabad sits on the Syr Darya in the southern part of Tashkent Province, right on the border with Tajikistan. With around 95,000 inhabitants, the city is best known as the home of Central Asia's largest steel plant, Uzmetkombinat. It was founded in 1942 when Soviet heavy-industry plants were relocated eastward away from the advancing German front. The works still employ several thousand people and produce rolled steel, rebar, and railway rails. The city also hosts a major cement plant and a hydroelectric station on the Fars-Hatchan reservoir. Bekabad has a geopolitical dimension too: the railway and road links cross the Tajik-Uzbek border several times, which has led to complicated transit arrangements since the two countries became independent.",
      es: "Bekabad se encuentra a orillas del Sir Daria, en el sur de la provincia de Tashkent, justo en la frontera con Tayikistán. Con unos 95.000 habitantes, la ciudad es conocida principalmente como la sede de la acería más grande de Asia Central, el Uzmetkombinat. Fue fundada en 1942, cuando las plantas de industria pesada soviéticas fueron trasladadas hacia el este ante el avance del frente alemán. Hasta hoy, la planta emplea a varios miles de personas y produce acero laminado, acero de refuerzo y rieles ferroviarios. Además, cuenta con una importante planta de cemento y una central hidroeléctrica en el embalse de Farhad. Bekabad también desempeña un papel geopolítico, ya que las conexiones ferroviarias y por carretera cruzan varias veces la frontera entre Tayikistán y Uzbekistán, lo que llevó a soluciones de tránsito complicadas tras la independencia de ambos países.",
      pt: "Bekobod está localizada no Syr Darya, no sul da província de Tashkent, mesmo na fronteira com o Tajiquistão. Com cerca de 95.000 habitantes, a cidade é conhecida principalmente como a sede da maior siderúrgica da Ásia Central, a Uzmetkombinat. Foi fundada em 1942, quando as fábricas soviéticas de indústria pesada foram transferidas para leste devido ao avanço da frente alemã. Até hoje, a fábrica emprega vários milhares de pessoas e produz aço laminado, aço de reforço e carris ferroviários. Além disso, existe uma importante fábrica de cimento e uma central hidroelétrica na barragem de Farhad. Bekobod também desempenha um papel geopolítico, uma vez que as ligações ferroviárias e rodoviárias cruzam várias vezes a fronteira tajique-uzbeque, o que levou a soluções de trânsito complicadas após a independência dos dois países.",
      fr: "Bekabad se situe au bord du Syr-Daria, au sud de la province de Tachkent, directement à la frontière avec le Tadjikistan. Avec environ 95 000 habitants, la ville est surtout connue pour abriter le plus grand complexe sidérurgique d'Asie centrale, l'Uzmetkombinat. Il a été fondé en 1942, lorsque les usines d'industrie lourde soviétiques furent déplacées vers l'est pour fuir l'avancée du front allemand. Aujourd'hui encore, l'usine emploie plusieurs milliers de personnes et produit de l'acier laminé, des fers à béton et des rails de chemin de fer. On y trouve également une importante cimenterie et une centrale hydroélectrique sur le réservoir de Farhad. Bekabad joue aussi un rôle géopolitique, car les liaisons ferroviaires et routières traversent plusieurs fois la frontière tadjiko-ouzbèke, ce qui a nécessité des solutions de transit complexes après l'indépendance des deux pays.",
    },
