    type: "city",
    parent: "UZ-QA",
    coords: [66.8253, 39.0525],
    name: { de: "Schahrisabs", hu: "Sahriszabz", ro: "Șahrisabz", en: "Shahrisabz"},
    image: "/poi-images/shahrisabz-cities-v2.webp",
    description: {
      de: "Die historische Geburtsstadt von Timur mit bedeutenden architektonischen Ruinen.",
      hu: "Timur történelmi szülővárosa jelentős építészeti romokkal.",
      ro: "Orașul natal istoric al lui Timur, cu ruine arhitecturale semnificative.",
      en: "The historical birthplace of Timur with significant architectural ruins.",
      es: "La ciudad histórica natal de Tamerlán con importantes ruinas arquitectónicas.",
      pt: "A cidade histórica natal de Tamerlão com importantes ruínas arquitetónicas.",
      fr: "La ville historique natale de Tamerlan, abritant d'importants vestiges architecturaux.",
    },
    descriptionAdvanced: {
      de: "Shahrisabz, südlich von Samarkand gelegen, ist eine der geschichtsträchtigsten Städte Usbekistans und weltweit als Geburtsort des Eroberers Timur (Tamerlan) bekannt. Die Stadt, deren Name 'Grüne Stadt' bedeutet, war im 14. und 15. Jahrhundert eine wichtige Residenz der Timuriden. Das beeindruckendste Monument sind die Ruinen des Ak-Saray-Palastes, dessen gewaltige Portalwände einst 65 Meter hoch waren und mit spektakulären blauen Kacheln verziert sind. Weitere bedeutende Komplexe sind Dorut Tilavat mit der Gök-Gumbas-Moschee und Dorus Saodat, wo sich das leere Grab Timurs befindet. Das historische Zentrum von Shahrisabz wurde im Jahr 2000 in das UNESCO-Weltkulturerbe aufgenommen. Trotz der Zerstörungen durch spätere Eroberer wie das Khanat von Buchara zeugen die verbliebenen Bauten von der einstigen Pracht der timuridischen Architektur. Heute ist die Stadt ein wichtiges Pilger- und Touristenziel, das seinen ursprünglichen Charakter und sein traditionelles Handwerk bewahrt hat.",
      hu: "Sahriszabz város Üzbegisztán déli részén, Szamarkand közelében található, és világszerte Timur Lenk (Tamerlán), a nagy hódító szülőhelyeként ismert. A város neve perzsa nyelven 'zöld várost' jelent, ami a környék buja növényzetére utal. A 14-15. században a Timurida-dinasztia egyik legfontosabb központja volt. Leglátványosabb emléke az Ak-Szaraj (Fehér Palota) monumentális romjai, amelynek kapubástyái egykor 65 méter magasak voltak, és ma is lenyűgöző kék mozaikok díszítik őket. További fontos helyszínek a Dorut Tilavat komplexum a Gök Gumbas mecsettel, valamint a Dorusz Szaodat, ahol Timur eredetileg tervezett sírhelye található. Sahriszabz történelmi központja 2000 óta az UNESCO Világörökség része. Bár a későbbi évszázadokban, például a Buharai Kánság idején jelentős pusztítás érte, a fennmaradt épületek ma is hirdetik a timurida építészet egykori dicsőségét.",
      ro: "Shahrisabz, situat la sud de Samarkand, este unul dintre cele mai vechi orașe din Uzbekistan, faimos la nivel mondial drept locul de naștere al marelui cuceritor Timur Lenk. Numele orașului se traduce prin 'Orașul Verde', reflectând vegetația bogată a zonei. În secolele XIV și XV, a servit drept reședință secundară importantă pentru dinastia Timuridă. Cel mai impresionant monument este reprezentat de ruinele Palatului Ak-Saray (Palatul Alb), ale cărui porți monumentale atingeau odinioară înălțimea de 65 de metri, fiind acoperite cu mozaicuri albastre fine. Alte situri de importanță majoră sunt complexele Dorut Tilavat, cu moscheea Gök Gumbas, și Dorus Saodat, unde se află cripta destinată inițial lui Timur. Centrul istoric a fost inclus în Patrimoniul Mondial UNESCO în anul 2000. Deși a suferit distrugeri în perioadele ulterioare, vestigiile actuale rămân dovezi clare ale splendorii arhitecturale timuride.",
      en: "Shahrisabz, located south of Samarkand, is one of Uzbekistan's most ancient cities and is globally renowned as the birthplace of the conqueror Amir Timur (Tamerlane). Its name means 'Green City' in Persian, a nod to the lush surroundings of the region. During the 14th and 15th centuries, Timur transformed the city into a magnificent residence for the Timurid dynasty. The most imposing landmark is the ruins of the Ak-Saray Palace, whose gateway towers once stood 65 meters high and are still covered in stunning blue tile mosaics. Other vital sites include the Dorut Tilavat complex, featuring the Kok Gumbaz Mosque, and the Dorus Saodat complex, which houses the tomb originally intended for Timur. The historic center of Shahrisabz was designated a UNESCO World Heritage site in 2000. Despite partial destruction by later rulers of Bukhara, the city's monumental remains continue to showcase the grandeur of Timurid imperial architecture.",
      es: "Shakhrisabz, que significa 'ciudad verde', se encuentra a unos 80 kilómetros al sur de Samarcanda, al pie de las montañas Hissar. Es la ciudad natal del gran conquistador Tamerlán, que nació aquí en 1336 y regaló a su ciudad natal magníficos edificios durante toda su vida. El emblema es el gigantesco palacio Ak-Saray, del que hoy todavía se conservan los pilones de entrada de unos 38 metros de altura; en el pasado se dice que las torres alcanzaban más de 60 metros. También los complejos Dorut-Tilavat y Dorus-Saodat, con el mausoleo del hijo de Tamerlán, Jahangir, se encuentran entre los puntos destacados. En 2000, el centro histórico de Shakhrisabz fue declarado Patrimonio de la Humanidad por la UNESCO. Con unos 100.000 habitantes, la ciudad vive hoy de la agricultura (granadas, vino), la producción de seda y el turismo.",
      pt: "Shakhrisabz, que significa 'cidade verde', situa-se a cerca de 80 quilómetros a sul de Samarcanda, ao pé das montanhas Hissar. É a cidade natal do grande conquistador Tamerlão, que nasceu aqui em 1336 e presenteou a sua cidade natal com edifícios magníficos durante toda a sua vida. O emblema é o gigantesco palácio Ak-Saray, do qual ainda hoje se conservam os pilones de entrada com cerca de 38 metros de altura; no passado diz-se que as torres atingiam mais de 60 metros. Também os complexos Dorut-Tilavat e Dorus-Saodat, com o mausoléu do filho de Tamerlão, Jahangir, estão entre os pontos altos. Em 2000, o centro histórico de Shakhrisabz foi declarado Património Mundial pela UNESCO. Com cerca de 100.000 habitantes, a cidade vive hoje da agricultura (romãs, vinho), da produção de seda e do turismo.",
      fr: "Chakhrisabz, ce qui signifie « ville verte », est située à environ 80 kilomètres au sud de Samarcande, au pied des monts Hissar. C'est la ville natale du grand conquérant Tamerlan, qui y est né en 1336 et qui a doté sa ville d'origine de magnifiques édifices tout au long de sa vie. L'emblème de la ville est le gigantesque palais Ak-Saray, dont il reste aujourd'hui les pylônes d'entrée d'environ 38 mètres de haut ; autrefois, les tours auraient atteint plus de 60 mètres. Les complexes Dorout-Tilavat et Dorus-Saodat, abritant le mausolée du fils de Tamerlan, Jahangir, comptent également parmi les sites majeurs. En 2000, le centre historique de Chakhrisabz a été classé au patrimoine mondial de l'UNESCO. Avec environ 100 000 habitants, la ville vit aujourd'hui de l'agriculture (grenades, vin), de la production de soie et du tourisme.",
    },
