      es: ["Las ruinas del palacio Ak-Saray atestiguan el poder arquitectónico de Tamerlán en el siglo XIV.", "El nombre de la ciudad significa 'Ciudad Verde' en persa.", "El centro histórico de Shakhrisabz pertenece al Patrimonio de la Humanidad de la UNESCO desde el año 2000.", "La mezquita de Kok-Gumbaz del siglo XV es conocida por su enorme cúpula azul."],
      pt: ["As ruínas do palácio Ak-Saray testemunham o poder arquitetónico de Tamerlão no século XIV.", "O nome da cidade significa 'Cidade Verde' em persa.", "O centro histórico de Shakhrisabz pertence ao Património Mundial da UNESCO desde o ano 2000.", "A mesquita de Kok-Gumbaz do século XV é conhecida pela sua enorme cúpula azul."],
      fr: ["Les ruines du palais Ak-Saray témoignent de la puissance architecturale de Tamerlan au XIVe siècle.", "Le nom de la ville signifie « Ville verte » en persan.", "Le centre historique de Chakhrisabz est inscrit au patrimoine mondial de l'UNESCO depuis l'an 2000.", "La mosquée Kok-Gumbaz du XVe siècle est célèbre pour son immense dôme bleu."],
