    factsAdvanced: {
      de: ["Shahrisabz ist der Geburtsort von Timur Lenk, der hier im Jahr 1336 geboren wurde.", "Der Bau des Ak-Saray-Palastes begann im Jahr 1380 und dauerte über 20 Jahre.", "Die Portalwände des Palastes erreichen auch als Ruine noch eine Höhe von 38 Metern.", "Die Stadt wurde im Jahr 2000 zum UNESCO-Weltkulturerbe erklärt.", "Die Gök-Gumbas-Moschee wurde im Jahr 1437 von Ulugh Beg erbaut.", "Der Name Shahrisabz bedeutet im Persischen wörtlich 'Grüne Stadt'."],
      hu: ["Sahriszabz Timur Lenk szülőhelye, aki 1336-ban jött itt világra.", "Az Ak-Szaraj palota építése 1380-ban kezdődött és több mint 20 évig tartott.", "A palota megmaradt kapubástyái még ma is 38 méter magasak.", "A város történelmi központja 2000-ben került fel az UNESCO listájára.", "A Gök Gumbas mecsetet 1437-ben építtette Ulugbek.", "A város neve perzsa eredetű, jelentése szó szerint 'Zöld Város'."],
      ro: ["Shahrisabz este locul unde s-a născut Timur Lenk, în anul 1336.", "Construcția Palatului Ak-Saray a început în 1380 și a durat peste două decenii.", "Turnurile porții palatului măsoară și astăzi aproximativ 38 de metri înălțime.", "Orașul a fost inclus în lista Patrimoniului Mondial UNESCO în anul 2000.", "Moscheea Kok Gumbaz a fost ridicată în anul 1437 de către Ulugh Beg.", "Numele orașului înseamnă 'Orașul Verde' în limba persană."],
      en: ["Shahrisabz is the birthplace of Amir Timur, who was born there in 1336.", "Construction of the Ak-Saray Palace started in 1380 and took over 20 years.", "The remaining walls of the palace gateway still stand 38 meters tall today.", "The city's historic center was inscribed as a UNESCO World Heritage site in 2000.", "The Kok Gumbaz Mosque was commissioned by Ulugh Beg in 1437.", "The name Shahrisabz literally translates to 'Green City' from Persian."],
      es: ["Shakhrisabz se llamaba Kesh en la antigüedad.", "La UNESCO incluyó el centro histórico de la ciudad en su lista en el año 2000.", "El palacio Ak-Saray fue construido a partir de 1380 durante un período de 24 años.", "El portal del palacio Ak-Saray tenía originalmente unos 70 metros de altura.", "Amir Timur nació el 9 de abril de 1336 en el cercano pueblo de Hodja-Ilgar.", "La mezquita Kok-Gumbaz se traduce como 'Cúpula Azul'."],
      pt: ["Shakhrisabz chamava-se Kesh na antiguidade.", "A UNESCO incluiu o centro histórico da cidade na sua lista no ano 2000.", "O palácio Ak-Saray foi construído a partir de 1380 durante um período de 24 anos.", "O portal do palácio Ak-Saray tinha originalmente cerca de 70 metros de altura.", "Amir Timur nasceu a 9 de abril de 1336 na aldeia vizinha de Hodja-Ilgar.", "A mesquita Kok-Gumbaz traduz-se como 'Cúpula Azul'."],
      fr: ["Chakhrisabz s'appelait Kech dans l'Antiquité.", "Le patrimoine mondial de l'UNESCO comprend le centre historique de la ville depuis l'an 2000.", "Le palais Ak-Saray a été construit à partir de 1380 sur une période de 24 ans.", "Le portail du palais Ak-Saray mesurait initialement environ 70 mètres de haut.", "Amir Timur est né le 9 avril 1336 dans le village voisin de Hodja-Ilgar.", "Le nom de la mosquée Kok-Gumbaz signifie « dôme bleu »."],
    },
