    type: "city",
    parent: "UZ-SU",
    coords: [67.8986, 38.2667],
    name: { de: "Denau", hu: "Denau", ro: "Denov", en: "Denov"},
    image: "/poi-images/denov-cities-v2.webp",
    description: {
      de: "Handelszentrum in Südusbekistan mit einer florierenden Landwirtschaft und Weinproduktion.",
      hu: "Kereskedelmi központ Dél-Üzbegisztánban virágzó mezőgazdasággal és bortermeléssel.",
      ro: "Centru comercial în sudul Uzbekistanului cu o agricultură prosperă și producție de vin.",
      en: "Trade center in southern Uzbekistan with thriving agriculture and wine production.",
      es: "Centro comercial en el sur de Uzbekistán con una próspera agricultura y producción de vino.",
      pt: "Centro comercial no sul do Uzbequistão com uma próspera agricultura e produção de vinho.",
      fr: "Centre commercial du sud de l'Ouzbékistan doté d'une agriculture et d'une production viticole florissantes.",
    },
    descriptionAdvanced: {
      de: "Denov ist die zweitgrößte Stadt der südlichen Provinz Surchondarjo und liegt am Fluss Surchondarja in einem fruchtbaren Tal nahe der tadschikischen Grenze. Mit rund 90.000 Einwohnern ist sie ein wichtiges Handels- und Verwaltungszentrum für die Region. Die Geschichte der Stadt reicht bis ins 9. Jahrhundert zurück, als hier eine Karawanenstation an der südlichen Seidenstraße entstand. Berühmt ist Denov vor allem für seine Granatäpfel, Mandeln, Walnüsse und den heimischen Dolma-Sorten-Anbau, die in ganz Usbekistan begehrt sind. Auch der Tabakanbau hat Tradition. Industriell sind Lebensmittelverarbeitung, Baumwollentkernung und Textilien wichtig. In jüngster Zeit profitiert Denov von der wirtschaftlichen Belebung des grenznahen Surchan-Sonderwirtschaftsgebiets. Sehenswert sind die historische Said-Atalik-Madrassa und der lebhafte zentrale Basar.",
      hu: "Denov a déli Surhondarjo tartomány második legnagyobb városa, a Surhondarja folyó partján, egy termékeny völgyben, a tádzsik határ közelében. Mintegy 90 ezer lakosával fontos kereskedelmi és közigazgatási központ. A város története a 9. századig nyúlik vissza, amikor itt egy karavánállomás létesült a déli Selyemút mentén. Denov elsősorban gránátalmáiról, mandulájáról, dióiról és helyi szőlőfajtáiról híres, amelyek egész Üzbegisztánban keresettek. A dohánytermesztésnek is komoly hagyománya van. Iparilag az élelmiszer-feldolgozás, a gyapotmagtalanítás és a textilipar a meghatározó. Az utóbbi időben a város a határ menti Szurhán különleges gazdasági övezet fellendüléséből profitál. Látnivaló a történelmi Szaid-Atalik medresze és a forgalmas központi bazár.",
      ro: "Denov este al doilea mare oraș al provinciei sudice Surxondaryo, situat pe râul Surxondaryo, într-o vale fertilă din apropierea graniței cu Tadjikistan. Cu aproximativ 90.000 de locuitori, este un important centru comercial și administrativ al regiunii. Istoria orașului datează din secolul al IX-lea, când aici s-a format o stație de caravane pe ramura sudică a Drumului Mătăsii. Denov este vestit mai ales pentru rodii, migdale, nuci și soiurile locale de struguri, foarte căutate în întregul Uzbekistan. Cultivarea tutunului are și ea o tradiție îndelungată. Din punct de vedere industrial, sunt importante prelucrarea alimentelor, egrenarea bumbacului și industria textilă. Recent, Denov beneficiază de revigorarea economică a zonei economice speciale Surxon, aflată lângă graniță. Merită vizitate medreseaua istorică Said-Atalik și bazarul central animat.",
      en: "Denov is the second-largest city of southern Surxondaryo Province, set on the Surxondaryo River in a fertile valley near the Tajik border. With around 90,000 inhabitants, it is an important trade and administrative hub for the region. The town's history reaches back to the ninth century, when a caravan station arose here on the southern branch of the Silk Road. Denov is especially famous for its pomegranates, almonds, walnuts, and local grape varieties, which are prized throughout Uzbekistan. Tobacco growing also has a long tradition. Industrially, food processing, cotton ginning, and textiles are key. Recently the city has benefited from the economic revival of the nearby Surxon special economic zone on the border. Notable sights include the historic Said-Atalik madrasa and the lively central bazaar.",
      es: "Denov es la segunda ciudad más grande de la provincia sureña de Surjandaria y se encuentra a orillas del río Surjandaria en un fértil valle cerca de la frontera con Tayikistán. Con unos 90.000 habitantes, es un importante centro comercial y administrativo de la región. La historia de la ciudad se remonta al siglo IX, cuando surgió como una estación de caravanas en la Ruta de la Seda del sur. Denov es famosa sobre todo por sus granadas, almendras, nueces y el cultivo de variedades locales de dolma, muy codiciadas en todo Uzbekistán. El cultivo de tabaco también tiene tradición. Industrialmente, son importantes el procesamiento de alimentos, el desmotado de algodón y los textiles. Recientemente, Denov se beneficia de la reactivación económica de la zona económica especial de Surjan, cerca de la frontera. Merecen una visita la histórica madrasa Said-Atalik y el animado bazar central.",
      pt: "Denov é a segunda maior cidade da província de Surxondaryo e está localizada no rio Surxondaryo num vale fértil perto da fronteira com o Tajiquistão. Com cerca de 90.000 habitantes, é um importante centro comercial e administrativo para a região. A história da cidade remonta ao século IX, quando surgiu uma estação de caravanas na Rota da Seda do sul. Denov é famosa sobretudo pelas suas romãs, amêndoas, nozes e o cultivo de variedades locais de dolma, que são procuradas em todo o Uzbequistão. O cultivo do tabaco também tem tradição. Industrialmente, o processamento de alimentos, a descaroçamento de algodão e têxteis são importantes. Recentemente, Denov beneficia da revitalização económica da zona económica especial fronteiriça de Surxan. Vale a pena visitar a histórica Madraça Said-Atalik e o animado bazar central.",
      fr: "Denaou est la deuxième plus grande ville de la province méridionale de Sourkhandaria et se situe sur la rivière Sourkhandaria, dans une vallée fertile proche de la frontière tadjike. Avec environ 90 000 habitants, elle constitue un centre commercial et administratif majeur pour la région. L'histoire de la ville remonte au IXe siècle, lorsqu'une station de caravanes s'y installa sur la route méridionale de la Soie. Denaou est surtout réputée pour ses grenades, ses amandes, ses noix et la culture de variétés locales de dolmas, très prisées dans tout l'Ouzbékistan. La culture du tabac y est également traditionnelle. Sur le plan industriel, l'agroalimentaire, l'égrenage du coton et le textile sont prédominants. Récemment, Denaou a profité de la relance économique de la zone économique spéciale frontalière de Sourkhan. La médersa historique Said-Atalik et le bazar central animé méritent une visite.",
    },
