    name: { de: "Kattakurgan", hu: "Kattakurgon", ro: "Kattaqo'rg'on", en: "Kattakurgan"},
    image: "/poi-images/kattakurgan-cities-v2.webp",
    description: {
      de: "Eines der ältesten Zentren der Region Samarkand mit einem großen Wasserreservoir.",
      hu: "Szamarkand régió egyik legrégebbi központja, ahol egy nagy víztározó is található.",
      ro: "Unul dintre cele mai vechi centre ale regiunii Samarkand cu un mare rezervor de apă.",
      en: "One of the oldest centers of the Samarkand region with a large water reservoir.",
      es: "Uno de los centros más antiguos de la región de Samarcanda con un gran embalse.",
      pt: "Um dos centros mais antigos da região de Samarcanda com um grande reservatório de água.",
      fr: "L'un des centres les plus anciens de la région de Samarcande avec un grand réservoir d'eau.",
    },
    descriptionAdvanced: {
      de: "Kattakurgan liegt in der Provinz Samarkand, rund 65 Kilometer westlich der weltberühmten Oasenstadt, und blickt auf eine bewegte Geschichte zurück. Im 18. und 19. Jahrhundert war sie eine wichtige Festungsstadt des Emirats Buchara, bevor sie 1868 vom Russischen Reich erobert wurde. Mit etwa 80.000 Einwohnern ist Kattakurgan heute ein bedeutendes regionales Zentrum für Baumwollverarbeitung, Lebensmittelindustrie und Maschinenbau. Der nahegelegene Kattakurgan-Stausee ist mit über 800 Quadratkilometern Fläche einer der größten künstlichen Seen Zentralasiens und liefert Bewässerungswasser für die umliegenden Felder sowie Wasserkraft. Die Stadt hat zudem eine lebendige tadschikische und usbekische Mischbevölkerung. Sehenswert sind die alte russische Garnisonskirche, einige restaurierte Karawansereien und der traditionelle Wochenmarkt mit lokalem Honig und getrockneten Aprikosen.",
      hu: "Kattakurgán a Szamarkand tartományban fekszik, mintegy 65 kilométerre nyugatra a világhírű oázisvárostól, és mozgalmas múltra tekint vissza. A 18-19. században fontos erődvárosa volt a Buharai Emírségnek, mielőtt 1868-ban az Orosz Birodalom elfoglalta volna. Ma mintegy 80 ezer lakosával fontos regionális központ a gyapotfeldolgozás, az élelmiszeripar és a gépgyártás területén. A közeli Kattakurgáni-víztározó több mint 800 négyzetkilométeres területével Közép-Ázsia egyik legnagyobb mesterséges tava; a környező földeket öntözővízzel látja el, és vízerőművet is táplál. A városnak vegyes tádzsik-üzbég lakossága van, élénk hagyományokkal. Látnivaló a régi orosz helyőrségi templom, néhány felújított karavánszeráj és a hetipiac, ahol a helyi méz és aszalt sárgabarack a sláger.",
      ro: "Kattakurgan se află în provincia Samarkand, la aproximativ 65 de kilometri vest de celebrul oraș-oază, și are o istorie tumultuoasă. În secolele al XVIII-lea și al XIX-lea era un important oraș-cetate al Emiratului Buharei, până când, în 1868, a fost cucerit de Imperiul Rus. Cu aproximativ 80.000 de locuitori, Kattakurgan este astăzi un important centru regional pentru prelucrarea bumbacului, industria alimentară și construcția de mașini. Lacul de acumulare Kattakurgan, situat în apropiere, cu o suprafață de peste 800 de kilometri pătrați, este unul dintre cele mai mari lacuri artificiale din Asia Centrală, asigurând apă pentru irigarea câmpurilor din jur și energie hidroelectrică. Orașul are o populație mixtă tadjică și uzbecă, cu tradiții vii. Merită vizitate vechea biserică de garnizoană rusă, câteva caravanseraiuri restaurate și piața săptămânală, unde mierea locală și caisele uscate sunt vedete.",
      en: "Kattakurgan lies in Samarkand Province about 65 kilometres west of the world-famous oasis city and has a turbulent history of its own. In the eighteenth and nineteenth centuries it was an important fortress town of the Emirate of Bukhara, until it was conquered by the Russian Empire in 1868. With around 80,000 inhabitants, Kattakurgan is today a significant regional centre for cotton processing, food industries, and machine building. The nearby Kattakurgan Reservoir, covering more than 800 square kilometres, is one of Central Asia's largest artificial lakes, supplying irrigation water for the surrounding fields and hydroelectric power. The city has a lively mixed Tajik and Uzbek population. Worthwhile sights include the old Russian garrison church, several restored caravanserais, and the weekly market famous for local honey and dried apricots.",
      es: "Kattakurgan se encuentra en la provincia de Samarcanda, a unos 65 kilómetros al oeste de la mundialmente famosa ciudad oasis, y cuenta con una historia agitada. En los siglos XVIII y XIX, fue una importante ciudad fortaleza del Emirato de Bujará antes de ser conquistada por el Imperio Ruso en 1868. Con unos 80.000 habitantes, Kattakurgan es hoy un importante centro regional para el procesamiento de algodón, la industria alimentaria y la ingeniería mecánica. El cercano embalse de Kattakurgan, con más de 800 kilómetros cuadrados de superficie, es uno de los lagos artificiales más grandes de Asia Central y proporciona agua de riego para los campos circundantes, así como energía hidroeléctrica. La ciudad tiene además una vibrante población mixta de tayikos y uzbekos. Destacan la antigua iglesia de la guarnición rusa, algunos caravasares restaurados y el tradicional mercado semanal con miel local y albaricoques secos.",
      pt: "Kattakurgan localiza-se na província de Samarcanda, a cerca de 65 quilómetros a oeste da cidade oásis mundialmente famosa, e tem uma história movimentada. Nos séculos XVIII e XIX, foi uma importante cidade fortaleza do Emirado de Bucara, antes de ser conquistada pelo Império Russo em 1868. Com cerca de 80.000 habitantes, Kattakurgan é hoje um importante centro regional para o processamento de algodão, indústria alimentar e engenharia mecânica. O reservatório de Kattakurgan, nas proximidades, com mais de 800 quilómetros quadrados de superfície, é um dos maiores lagos artificiais da Ásia Central e fornece água de irrigação para os campos circundantes, bem como energia hidroeléctrica. A cidade tem também uma vibrante população mista de tajiques e usbeques. Locais de interesse incluem a antiga igreja da guarnição russa, alguns caravançarais restaurados e o tradicional mercado semanal com mel local e damascos secos.",
      fr: "Kattakourgan est située dans la province de Samarcande, à environ 65 kilomètres à l'ouest de la célèbre ville oasis, et possède une histoire mouvementée. Aux XVIIIe et XIXe siècles, elle fut une importante ville fortifiée de l'émirat de Boukhara, avant d'être conquise par l'Empire russe en 1868. Avec environ 80 000 habitants, Kattakourgan est aujourd'hui un centre régional majeur pour la transformation du coton, l'industrie alimentaire et la construction mécanique. Le réservoir de Kattakourgan tout proche, d'une superficie de plus de 800 kilomètres carrés, est l'un des plus grands lacs artificiels d'Asie centrale et fournit l'eau d'irrigation pour les champs environnants ainsi que de l'énergie hydroélectrique. La ville possède en outre une population mixte dynamique de Tadjiks et d'Ouzbeks. À voir : l'ancienne église de la garnison russe, quelques caravansérails restaurés et le marché hebdomadaire traditionnel proposant du miel local et des abricots secs.",
    },
