      es: ["En la ciudad se encuentra el segundo embalse más grande de Uzbekistán, el embalse de Kattakurgan.", "Fue fortificada en el siglo XVII por los emires de Bujará.", "Cuenta con uno de los teatros dramáticos uzbekos más antiguos, inaugurado en 1921.", "Es conocida por sus platos tradicionales de carne y su animado bazar dominical."],
      pt: ["A cidade abriga o segundo maior reservatório do Usbequistão, o reservatório de Kattakurgan.", "Foi fortificada no século XVII pelos emires de Bucara.", "Possui um dos teatros de drama usbeques mais antigos, inaugurado em 1921.", "É conhecida pelos seus pratos de carne tradicionais e pelo animado bazar de domingo."],
