    coords: [72.2411, 40.6425],
    name: { de: "Asaka", hu: "Aszaka", ro: "Asaka", en: "Asaka"},
    image: "/poi-images/asaka-cities-v2.webp",
    description: {
      de: "Eine Stadt im Ferghanatal, die vor allem für ihr großes Automobilwerk bekannt ist.",
      hu: "A Fergana-völgyben fekvő város, amely elsősorban hatalmas autógyáráról ismert.",
      ro: "Un oraș din Valea Fergana, cunoscut în special pentru marea sa fabrică de automobile.",
      en: "A city in the Fergana Valley, mostly known for its large automobile plant.",
      es: "Una ciudad del valle de Ferganá conocida principalmente por su gran planta de fabricación de automóviles.",
      pt: "Uma cidade no Vale de Fergana, conhecida principalmente pela sua grande fábrica de automóveis.",
      fr: "Une ville de la vallée de Ferghana, principalement connue pour son immense usine de fabrication automobile.",
    },
    descriptionAdvanced: {
      de: "Asaka liegt in der Provinz Andidschan im Ferghanatal und ist mit rund 75.000 Einwohnern als Automobilstadt Usbekistans bekannt. Hier befindet sich seit 1996 das größte Pkw-Werk Zentralasiens, das ursprünglich als Joint Venture mit der südkoreanischen Daewoo-Gruppe gegründet wurde und heute unter dem Namen UzAuto Motors als Tochter von General Motors operiert. Jährlich verlassen über 200.000 Fahrzeuge der Marken Chevrolet, Ravon und Cobalt das Werk, vor allem für den Inlandsmarkt sowie für den Export nach Russland und Kasachstan. Vor der Industrialisierung war Asaka ein eher ruhiger Marktflecken im fruchtbaren Ostteil des Ferghanatals; bis heute prägen Obstgärten, Baumwollfelder und Seidenraupenzucht das Umland. Die Stadt verfügt über moderne Wohnviertel, eine Berufsschule für Automechaniker und einen direkten Bahnanschluss.",
      hu: "Aszaka az Andidzsáni tartományban, a Fergánai-völgyben fekszik, és mintegy 75 ezer lakosával Üzbegisztán autóvárosaként ismert. Itt működik 1996 óta Közép-Ázsia legnagyobb autógyára, amelyet eredetileg a dél-koreai Daewoo csoporttal közös vállalkozásként alapítottak, és ma UzAuto Motors néven a General Motors leányvállalataként működik. Évente több mint 200 ezer Chevrolet, Ravon és Cobalt típusú jármű hagyja el a gyárat, főleg a belföldi piac, valamint Oroszország és Kazahsztán számára. Az iparosodás előtt Aszaka inkább csendes mezővároska volt a Fergánai-völgy keleti, termékeny részén; környékén ma is gyümölcsösök, gyapotmezők és selyemhernyó-tenyésztés a meghatározóak. A városnak modern lakónegyedei, autószerelő szakképző iskolája és közvetlen vasúti összeköttetése van.",
      ro: "Asaka este situat în provincia Andijan, în valea Fergana, și este cunoscut, cu aproximativ 75.000 de locuitori, drept orașul automobilelor din Uzbekistan. Aici funcționează, din 1996, cea mai mare uzină de autoturisme din Asia Centrală, înființată inițial ca un joint venture cu grupul sud-coreean Daewoo, iar astăzi parte a General Motors sub numele UzAuto Motors. Anual ies de pe poarta uzinei peste 200.000 de mașini Chevrolet, Ravon și Cobalt, destinate în principal pieței interne, dar și exportului spre Rusia și Kazahstan. Înainte de industrializare, Asaka era un târg liniștit din partea de est, fertilă, a văii Fergana; în jurul orașului se văd și astăzi livezi, lanuri de bumbac și creșteri de viermi de mătase. Orașul are cartiere de locuințe moderne, o școală profesională pentru mecanici auto și o legătură directă pe calea ferată.",
      en: "Asaka lies in Andijan Province in the Fergana Valley and, with around 75,000 inhabitants, is known as Uzbekistan's automotive city. Since 1996 it has been home to Central Asia's biggest passenger-car plant, originally founded as a joint venture with South Korea's Daewoo group and now operating as UzAuto Motors, a subsidiary of General Motors. More than 200,000 Chevrolet, Ravon, and Cobalt vehicles roll off the production line every year, mainly for the domestic market and for export to Russia and Kazakhstan. Before industrialisation Asaka was a quiet market town in the fertile eastern Fergana Valley; orchards, cotton fields, and silkworm farms still surround the city today. Asaka has modern residential districts, a vocational school for car mechanics, and a direct rail link.",
      es: "Asaka se encuentra en la provincia de Andiyán, en el valle de Ferganá, y es conocida como la ciudad del automóvil de Uzbekistán con sus cerca de 75.000 habitantes. Desde 1996, alberga la mayor planta de turismos de Asia Central, fundada originalmente como una empresa conjunta con el grupo surcoreano Daewoo y que hoy opera bajo el nombre de UzAuto Motors como filial de General Motors. Cada año, más de 200.000 vehículos de las marcas Chevrolet, Ravon y Cobalt salen de la fábrica, destinados principalmente al mercado nacional y a la exportación a Rusia y Kazajistán. Antes de la industrialización, Asaka era un tranquilo mercado en la fértil parte oriental del valle; hasta hoy, los huertos frutales, los campos de algodón y la cría de gusanos de seda marcan los alrededores. La ciudad cuenta con barrios residenciales modernos, una escuela de formación profesional para mecánicos de automóviles y conexión directa por ferrocarril.",
      pt: "Asaka está localizada na província de Andijon, no Vale de Fergana, e é conhecida como a cidade automóvel do Uzbequistão, com cerca de 75.000 habitantes. Desde 1996, abriga a maior fábrica de automóveis de passageiros da Ásia Central, originalmente fundada como uma joint venture com o grupo sul-coreano Daewoo e hoje operando sob o nome UzAuto Motors como subsidiária da General Motors. Anualmente, mais de 200.000 veículos das marcas Chevrolet, Ravon e Cobalt saem da fábrica, principalmente para o mercado interno e para exportação para a Rússia e o Cazaquistão. Antes da industrialização, Asaka era uma pacata vila mercantil na parte fértil do leste do vale; até hoje, pomares, campos de algodão e a criação de bicho-da-seda marcam os arredores. A cidade possui bairros residenciais modernos, uma escola profissional para mecânicos de automóveis e uma ligação ferroviária direta.",
      fr: "Asaka se situe dans la province d'Andijan, dans la vallée de Ferghana, et est connue comme la cité automobile de l'Ouzbékistan avec ses quelque 75 000 habitants. Depuis 1996, elle abrite la plus grande usine de voitures particulières d'Asie centrale, fondée à l'origine en tant que coentreprise avec le groupe sud-coréen Daewoo et opérant aujourd'hui sous le nom d'UzAuto Motors, filiale de General Motors. Chaque année, plus de 200 000 véhicules des marques Chevrolet, Ravon et Cobalt sortent de l'usine, principalement pour le marché intérieur ainsi que pour l'exportation vers la Russie et le Kazakhstan. Avant l'industrialisation, Asaka était un bourg tranquille dans la partie fertile de l'est de la vallée ; aujourd'hui encore, les vergers, les champs de coton et l'élevage de vers à soie marquent les environs. La ville dispose de quartiers résidentiels modernes, d'une école professionnelle pour mécaniciens automobiles et d'une liaison ferroviaire directe.",
    },
