      pt: ["O nome da cidade significa literalmente 'Caminho Novo' em uzbeque.", "Desenvolveu-se rapidamente devido ao estabelecimento de grandes empresas de processamento de alimentos.", "Uma das cidades satélite mais importantes da capital, Tashkent.", "Inúmeras fábricas de doces e massas têm a sua sede aqui."],
