      fr: ["Khodjeyli est située à environ 15 kilomètres à l'ouest de Noukous.", "Le complexe antique de Mizdakhan couvre plus de 200 hectares.", "La ville a reçu le statut de ville en 1926.", "Khodjeyli est un arrêt important sur la ligne de chemin de fer vers le Turkménistan.", "La ville est réputée pour ses usines de textile et de vêtements.", "Khodjeyli est l'une des plus anciennes villes habitées en continu du Karakalpakstan."],
